import React from 'react';
import { IconProps, ICON_REGISTRY } from '@/config/icons';

export const Icon: React.FC<IconProps> = ({
  name,
  size = 24,
  color = 'currentColor',
  variant = 'filled',
  className = '',
  style = {},
}) => {
  const iconConfig = ICON_REGISTRY[name];

  if (!iconConfig) {
    console.warn(`Icon "${name}" not found in icon registry`);
    return null;
  }

  const iconStyle: React.CSSProperties = {
    width: `${size}px`,
    height: `${size}px`,
    color,
    ...style,
  };

  return (
    <svg
      viewBox="0 0 24 24"
      fill={variant === 'filled' ? 'currentColor' : 'none'}
      stroke={variant === 'outline' ? 'currentColor' : 'none'}
      strokeWidth={variant === 'outline' ? 2 : 0}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
      style={iconStyle}
    >
      {iconConfig.component()}
    </svg>
  );
};

Icon.displayName = 'Icon';