import React from 'react';
import { Icon } from '@/components/icons/Icon';

export type ButtonStyle = 'solid' | 'outline' | 'gradient' | 'glowing' | 'minimal';
export type ButtonShape = 'pill' | 'rounded' | 'square' | 'custom';
export type ButtonAnimation = 'pulse' | 'glow' | 'bounce' | 'shake' | 'none';

interface CTAButtonProps {
  text: string;
  style?: ButtonStyle;
  shape?: ButtonShape;
  icon?: string;
  iconPosition?: 'left' | 'right' | 'center';
  animation?: ButtonAnimation;
  pillarColor: string;
  backgroundColor: string;
  size?: 'small' | 'medium' | 'large';
}

export const CTAButton: React.FC<CTAButtonProps> = ({
  text,
  style = 'solid',
  shape = 'pill',
  icon,
  iconPosition = 'right',
  animation = 'pulse',
  pillarColor,
  backgroundColor,
  size = 'large',
}) => {
  const sizes = {
    small: { padding: '12px 24px', fontSize: 24, iconSize: 20 },
    medium: { padding: '16px 32px', fontSize: 28, iconSize: 24 },
    large: { padding: '20px 48px', fontSize: 32, iconSize: 28 },
  };

  const currentSize = sizes[size];

  const getButtonStyle = (): React.CSSProperties => {
    switch (style) {
      case 'solid':
        return {
          backgroundColor: pillarColor,
          color: backgroundColor,
          border: 'none',
        };
      case 'outline':
        return {
          backgroundColor: 'transparent',
          color: pillarColor,
          border: `2px solid ${pillarColor}`,
        };
      case 'gradient':
        return {
          background: `linear-gradient(135deg, ${pillarColor}, ${backgroundColor})`,
          color: backgroundColor,
          border: 'none',
        };
      case 'glowing':
        return {
          backgroundColor: pillarColor,
          color: backgroundColor,
          border: 'none',
          boxShadow: `0 0 20px ${pillarColor}80`,
        };
      case 'minimal':
        return {
          backgroundColor: 'transparent',
          color: pillarColor,
          border: 'none',
          borderBottom: `2px solid ${pillarColor}`,
          borderRadius: '0',
        };
      default:
        return {};
    }
  };

  const getButtonShape = (): React.CSSProperties => {
    switch (shape) {
      case 'pill':
        return { borderRadius: '9999px' };
      case 'rounded':
        return { borderRadius: '12px' };
      case 'square':
        return { borderRadius: '0px' };
      case 'custom':
        return { borderRadius: '4px' };
      default:
        return {};
    }
  };

  const getAnimationStyle = (): React.CSSProperties => {
    switch (animation) {
      case 'pulse':
        return { animation: 'pulse 2s infinite' };
      case 'glow':
        return { animation: 'glow 2s infinite' };
      case 'bounce':
        return { animation: 'bounce 2s infinite' };
      case 'shake':
        return { animation: 'shake 2s infinite' };
      case 'none':
        return {};
      default:
        return {};
    }
  };

  const buttonStyle = {
    ...getButtonStyle(),
    ...getButtonShape(),
    ...getAnimationStyle(),
    padding: currentSize.padding,
    fontSize: `${currentSize.fontSize}px`,
    display: 'inline-flex',
    alignItems: 'center',
    gap: '12px',
    fontWeight: 700,
    cursor: 'pointer',
    transition: 'all 0.3s ease',
  };

  const iconColor = getButtonStyle().color || pillarColor;

  return (
    <div style={buttonStyle}>
      {icon && iconPosition === 'left' && <Icon name={icon} size={currentSize.iconSize} color={iconColor} />}
      <span>{text}</span>
      {icon && iconPosition === 'right' && <Icon name={icon} size={currentSize.iconSize} color={iconColor} />}
    </div>
  );
};