'use client';

import React, { useState, useRef, useCallback } from 'react';
import { useCarouselStore } from '@/store/carousel-store';
import { ThemedSlide } from '../preview/ThemedSlide';
import { ExportProgress } from './ExportProgress';
import { exportSlideAsPng, downloadDataUrl } from '@/lib/export/png-exporter';
import { createZipFromExports } from '@/lib/export/batch-exporter';
import { ExportSettings } from '@/types/index';
import { X, Download, Image, Archive } from 'lucide-react';

interface ExportDialogProps {
  isOpen: boolean;
  onClose: () => void;
}

export function ExportDialog({ isOpen, onClose }: ExportDialogProps) {
  const { carousel, exportSettings, setExportSettings } = useCarouselStore();
  const [isExporting, setIsExporting] = useState(false);
  const [progress, setProgress] = useState({ current: 0, total: 0 });
  const slideRefs = useRef<(HTMLDivElement | null)[]>([]);

  const handleExportSingle = useCallback(async (index: number) => {
    if (!carousel) return;

    const element = slideRefs.current[index];
    if (!element) return;

    setIsExporting(true);
    setProgress({ current: 0, total: 1 });

    try {
      const filename = `${carousel.name}_slide_${String(index + 1).padStart(2, '0')}`;
      const result = await exportSlideAsPng(element, filename, exportSettings);
      downloadDataUrl(result.dataUrl, result.filename);
      setProgress({ current: 1, total: 1 });
    } catch (error) {
      console.error('Export failed:', error);
      alert('Export failed. Please try again.');
    } finally {
      setIsExporting(false);
    }
  }, [carousel, exportSettings]);

  const handleExportAll = useCallback(async () => {
    if (!carousel) return;

    setIsExporting(true);
    const total = carousel.slides.length;
    setProgress({ current: 0, total });

    try {
      const exports = [];

      for (let i = 0; i < carousel.slides.length; i++) {
        const element = slideRefs.current[i];
        if (!element) continue;

        setProgress({ current: i + 1, total });

        const filename = `${carousel.name}_slide_${String(i + 1).padStart(2, '0')}`;
        const result = await exportSlideAsPng(element, filename, exportSettings);
        exports.push(result);

        // Small delay for UI update
        await new Promise((resolve) => setTimeout(resolve, 100));
      }

      await createZipFromExports(exports, `${carousel.name}_carousel`);
    } catch (error) {
      console.error('Export failed:', error);
      alert('Export failed. Please try again.');
    } finally {
      setIsExporting(false);
    }
  }, [carousel, exportSettings]);

  if (!isOpen || !carousel) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80">
      <div className="bg-gray-900 rounded-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-white/10">
          <h2 className="text-xl font-bold text-white">Export Carousel</h2>
          <button
            onClick={onClose}
            className="p-2 text-white/60 hover:text-white hover:bg-white/10 rounded-lg transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Settings */}
        <div className="p-4 border-b border-white/10">
          <div className="flex flex-wrap gap-6">
            <div>
              <label className="block text-sm font-medium text-white/70 mb-2">
                Pixel Ratio
              </label>
              <div className="flex gap-2">
                {([1, 2, 3] as const).map((ratio) => (
                  <button
                    key={ratio}
                    onClick={() => setExportSettings({ pixelRatio: ratio })}
                    className={`px-4 py-2 rounded-lg text-sm transition-colors ${
                      exportSettings.pixelRatio === ratio
                        ? 'bg-white text-black'
                        : 'bg-white/10 text-white/70 hover:bg-white/20'
                    }`}
                  >
                    {ratio}x
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-white/70 mb-2">
                Format
              </label>
              <div className="flex gap-2">
                {(['png', 'jpeg'] as const).map((format) => (
                  <button
                    key={format}
                    onClick={() => setExportSettings({ format })}
                    className={`px-4 py-2 rounded-lg text-sm uppercase transition-colors ${
                      exportSettings.format === format
                        ? 'bg-white text-black'
                        : 'bg-white/10 text-white/70 hover:bg-white/20'
                    }`}
                  >
                    {format}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* Slides Grid */}
        <div className="flex-1 p-4 overflow-y-auto">
          <div className="grid grid-cols-3 md:grid-cols-5 gap-4">
            {carousel.slides.map((slide, index) => (
              <div key={slide.id} className="relative group">
                <div className="aspect-[4/5] bg-gray-800 rounded-lg overflow-hidden">
                  <div
                    style={{ transform: 'scale(0.1)', transformOrigin: 'top left' }}
                  >
                    <div
                      ref={(el) => {
                        slideRefs.current[index] = el;
                      }}
                    >
                      <ThemedSlide
                        slide={slide}
                        pillar={carousel.pillar}
                        carouselTotalSlides={carousel.slides.length}
                        carouselBackgroundPack={carousel.carouselBackgroundPack}
                      />
                    </div>
                  </div>
                </div>
                <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                  <button
                    onClick={() => handleExportSingle(index)}
                    disabled={isExporting}
                    className="p-2 bg-white text-black rounded-lg hover:bg-white/90 transition-colors disabled:opacity-50"
                  >
                    <Image className="w-4 h-4" />
                  </button>
                </div>
                <div className="absolute top-2 left-2 px-2 py-1 bg-black/70 rounded text-xs text-white">
                  {index + 1}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Progress */}
        {isExporting && (
          <div className="p-4 border-t border-white/10">
            <ExportProgress
              current={progress.current}
              total={progress.total}
              label="Exporting slides..."
            />
          </div>
        )}

        {/* Footer */}
        <div className="p-4 border-t border-white/10 flex justify-end gap-4">
          <button
            onClick={onClose}
            className="px-6 py-2 text-white/70 hover:text-white transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={handleExportAll}
            disabled={isExporting}
            className="flex items-center gap-2 px-6 py-2 bg-gradient-to-r from-blue-500 to-purple-500 text-white rounded-lg hover:opacity-90 transition-opacity disabled:opacity-50"
          >
            <Archive className="w-4 h-4" />
            Export All as ZIP
          </button>
        </div>
      </div>
    </div>
  );
}
